:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #fd79a8;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --card-back: #3a3a55;
  --matched: #00b894;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.game-container {
  background: var(--surface);
  border-radius: 1.5rem;
  padding: 2rem;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
}

.game-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.subtitle {
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.stats {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.stat {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--accent);
}

.btn {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: #5a4bd1;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border-radius: 0.75rem;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s, background 0.3s;
  border: 2px solid transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  user-select: none;
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:hover:not(.matched):not(.flipped) {
  transform: scale(1.05);
  background: #4a4a6a;
}

.card.flipped {
  background: var(--surface);
  border-color: var(--primary);
  color: var(--text);
}

.card.matched {
  background: var(--matched);
  border-color: var(--matched);
  cursor: default;
  color: #fff;
}

.card .color-swatch {
  width: 60%;
  height: 60%;
  border-radius: 0.5rem;
  display: none;
}

.card.flipped .color-swatch,
.card.matched .color-swatch {
  display: block;
}

.win-message {
  text-align: center;
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--accent);
  margin-top: 1rem;
  animation: pop 0.4s ease;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

@media (max-width: 400px) {
  .game-container {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  .game-board {
    gap: 0.5rem;
  }
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

const board = document.getElementById('game-board');
const moveCounter = document.getElementById('move-counter');
const newGameBtn = document.getElementById('new-game-btn');
const winMessage = document.getElementById('win-message');

let cards = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lockBoard = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createCards() {
  const deck = [];
  COLORS.forEach((color, i) => {
    deck.push({ id: i, color });
    deck.push({ id: i, color });
  });
  return shuffle(deck);
}

function renderBoard() {
  board.innerHTML = '';
  cards.forEach((card, index) => {
    const el = document.createElement('div');
    el.className = 'card';
    el.setAttribute('role', 'gridcell');
    el.setAttribute('tabindex', '0');
    el.setAttribute('aria-label', 'Hidden card');
    el.dataset.index = index;

    const swatch = document.createElement('div');
    swatch.className = 'color-swatch';
    swatch.style.backgroundColor = card.color;
    el.appendChild(swatch);

    el.addEventListener('click', () => handleCardClick(index));
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleCardClick(index);
      }
    });

    board.appendChild(el);
  });
}

function handleCardClick(index) {
  if (lockBoard) return;
  const cardEl = board.children[index];
  if (cardEl.classList.contains('flipped') || cardEl.classList.contains('matched')) return;

  cardEl.classList.add('flipped');
  cardEl.setAttribute('aria-label', 'Flipped card');
  flipped.push(index);

  if (flipped.length === 2) {
    moves++;
    moveCounter.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  const [i1, i2] = flipped;
  const card1 = cards[i1];
  const card2 = cards[i2];
  const el1 = board.children[i1];
  const el2 = board.children[i2];

  if (card1.id === card2.id) {
    el1.classList.add('matched');
    el2.classList.add('matched');
    el1.setAttribute('aria-label', 'Matched card');
    el2.setAttribute('aria-label', 'Matched card');
    matched++;
    flipped = [];
    if (matched === COLORS.length) {
      winMessage.hidden = false;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      el1.classList.remove('flipped');
      el2.classList.remove('flipped');
      el1.setAttribute('aria-label', 'Hidden card');
      el2.setAttribute('aria-label', 'Hidden card');
      flipped = [];
      lockBoard = false;
    }, 800);
  }
}

function resetGame() {
  cards = createCards();
  flipped = [];
  matched = 0;
  moves = 0;
  lockBoard = false;
  moveCounter.textContent = 'Moves: 0';
  winMessage.hidden = true;
  renderBoard();
}

newGameBtn.addEventListener('click', resetGame);

resetGame();
